def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, qty)
    sell_book = []  # List of (price, arrival_time, id, qty)
    order_map = {}  # Maps id to (side, price, qty, arrival_time, cancelled)
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, qty, arr_time, cancelled = order_map[order_id]
                if not cancelled and qty > 0:
                    order_map[order_id] = (side, price, 0, arr_time, True)
                    if side == 'buy':
                        buy_book[:] = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != order_id]
                    else:
                        sell_book[:] = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != order_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = order[3] if order_type != 'market' else None

            order_map[order_id] = (side, price, qty, arrival_time, False)
            arrival_time += 1

            if side == 'buy':
                while qty > 0 and sell_book:
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    best_sell_price, best_sell_time, best_sell_id, best_sell_qty = sell_book[0]

                    if order_type == 'market' or price >= best_sell_price:
                        trade_qty = min(qty, best_sell_qty)
                        trade_price = best_sell_price
                        trades.append([order_id, best_sell_id, trade_price, trade_qty])

                        qty -= trade_qty
                        best_sell_qty -= trade_qty

                        if best_sell_qty > 0:
                            sell_book[0] = (best_sell_price, best_sell_time, best_sell_id, best_sell_qty)
                            _, _, _, old_qty, _ = order_map[best_sell_id]
                            order_map[best_sell_id] = (order_map[best_sell_id][0], order_map[best_sell_id][1], best_sell_qty, order_map[best_sell_id][3], False)
                        else:
                            sell_book.pop(0)
                            order_map[best_sell_id] = (order_map[best_sell_id][0], order_map[best_sell_id][1], 0, order_map[best_sell_id][3], False)
                    else:
                        break

                if qty > 0 and order_type == 'limit':
                    buy_book.append((price, arrival_time - 1, order_id, qty))
                    order_map[order_id] = (side, price, qty, arrival_time - 1, False)
                elif qty > 0:
                    order_map[order_id] = (side, price, 0, arrival_time - 1, False)

            else:  # sell
                while qty > 0 and buy_book:
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    best_buy_price, best_buy_time, best_buy_id, best_buy_qty = buy_book[0]

                    if order_type == 'market' or price <= best_buy_price:
                        trade_qty = min(qty, best_buy_qty)
                        trade_price = best_buy_price
                        trades.append([best_buy_id, order_id, trade_price, trade_qty])

                        qty -= trade_qty
                        best_buy_qty -= trade_qty

                        if best_buy_qty > 0:
                            buy_book[0] = (best_buy_price, best_buy_time, best_buy_id, best_buy_qty)
                            order_map[best_buy_id] = (order_map[best_buy_id][0], order_map[best_buy_id][1], best_buy_qty, order_map[best_buy_id][3], False)
                        else:
                            buy_book.pop(0)
                            order_map[best_buy_id] = (order_map[best_buy_id][0], order_map[best_buy_id][1], 0, order_map[best_buy_id][3], False)
                    else:
                        break

                if qty > 0 and order_type == 'limit':
                    sell_book.append((price, arrival_time - 1, order_id, qty))
                    order_map[order_id] = (side, price, qty, arrival_time - 1, False)
                elif qty > 0:
                    order_map[order_id] = (side, price, 0, arrival_time - 1, False)

    return trades

